// The listening page: each class's skills; cast and hit, old (?vurus=eski) and new. The sounds are the game's own code
// (game-sound.js, generated by build.mjs). Which events a skill plays is read from the game's sound calls.
import { start, play, hit, kill } from './game-sound.js';

// [skill id, name, element of its hit, cast events, hit events]. An event 'name@k' passes a strength k; 'c:name' is a
// shared event (sfx); a function plays inline sounds of the game (f(api, newSet)).
