const CLASSES = [['mage', 'Büyücü', MAGE], ['necro', 'Ölü Çağıran', NECRO], ['knight', 'Şövalye', KNIGHT], ['ranger', 'Okçu', RANGER], ['rogue', 'Haydut', ROGUE], ['barb', 'Barbar', null]];
const EL_TR = { fire: 'ateş', cold: 'buz', light: 'şimşek', pois: 'zehir', shad: 'gölge', holy: 'kutsal', phys: 'fiziksel' };
const KILL_EL = { mage: ['fire', 'cold', 'light'], necro: ['phys', 'pois'], knight: ['phys', 'holy'], ranger: ['phys', 'fire'], rogue: ['phys', 'pois', 'shad'] };

const app = document.getElementById('app'), go = document.getElementById('go');
const btn = (t, nw, f) => { const b = document.createElement('button'); b.textContent = t; if (nw) b.className = 'n'; b.onclick = f; return b; };
// three sets: eski (the old hits), şimdi (the element hits of the first round), gerçekçi (real recorded foley)
const pair = (label, f) => { const d = document.createElement('div'), i = document.createElement('i'); i.textContent = label; d.append(i, btn('Eski', false, () => f('eski')), btn('Şimdi', false, () => f('simdi')), btn('Gerçekçi', true, () => f('gercek'))); return d; };
let cur = 'mage';
function render() {
  app.innerHTML = '';
  const tabs = document.createElement('div'); tabs.className = 'tabs';
  for (const [id, tr] of CLASSES) { const b = btn(tr, false, () => { cur = id; render(); }); if (id === cur) b.className = 'on'; tabs.append(b); }
  app.append(tabs);
  const C = CLASSES.find((c) => c[0] === cur);
  if (!C[2]) { const n = document.createElement('div'); n.className = 'note'; n.textContent = 'Barbarın sesleri değişmedi: baltası ve sesi senin 20 Ekim\'de seçtiğin set (balta vuruşu vurduğu şeye göre, gerçek kayıtlar).'; app.append(n); return; }
  const cls = C[0];
  const sec = (t) => { const d = document.createElement('div'); d.className = 'sec'; d.textContent = t; app.append(d); };
  sec('Vuruş sınaması');
  const r0 = document.createElement('div'); r0.className = 'row';
  const n0 = document.createElement('div'); n0.className = 'nm'; n0.innerHTML = '<b>Hızlı vuruş: 8 vuruş art arda</b><span>Bir sürüye arka arkaya isabet — yenide üst üste binip gürültüye dönmemeli</span>';
  const b0 = document.createElement('div'); b0.className = 'bt';
  const sk0 = C[2][0];
  b0.append(pair('8 vuruş', (nw) => { for (let i = 0; i < 8; i++) setTimeout(() => hit(cls, sk0[0], sk0[2], nw), i * 65); }));
  r0.append(n0, b0); app.append(r0);
  for (const el of KILL_EL[cls]) {
    const r = document.createElement('div'); r.className = 'row'; const nm = document.createElement('div'); nm.className = 'nm'; nm.innerHTML = `<b>Öldürme (${EL_TR[el]})</b><span>Son vuruş ve canavarın düşüşü</span>`;
    const bt = document.createElement('div'); bt.className = 'bt'; bt.append(pair('ölüm', (nw) => { hit(cls, sk0[0], el, nw); kill(cls, el, nw); })); r.append(nm, bt); app.append(r);
  }
  sec('Yetenekler');
  for (const [sk, name, el, cast, hits] of C[2]) {
    const r = document.createElement('div'); r.className = 'row'; const nm = document.createElement('div'); nm.className = 'nm';
    nm.innerHTML = `<b>${name}</b><span>${EL_TR[el]}</span>`;
    const bt = document.createElement('div'); bt.className = 'bt';
    if (cast.length) bt.append(pair('atış', (nw) => play(cls, cast, nw))); else bt.append(document.createElement('div'));
    bt.append(pair('vuruş', (nw) => { play(cls, hits, nw); hit(cls, sk, el, nw); }));
    r.append(nm, bt); app.append(r);
  }
}
go.onclick = async () => {
  go.disabled = true; go.textContent = 'Yükleniyor…';
  try {
  const files = await (await fetch('files.json')).json(); let done = 0, ok = 0; const bad = []; window.__bad = bad;
  await start(async (get) => { const q = files.slice(); const w = async () => { while (q.length) { const f = q.shift(); try { await get(f); ok++; } catch (e) { bad.push(f); } done++; go.textContent = 'Yükleniyor… ' + Math.round((100 * done) / files.length) + '%'; } }; await Promise.all([w(), w(), w(), w(), w(), w()]); });
  window.__loaded = [ok, files.length]; const st = document.createElement('p'); st.textContent = ok + ' / ' + files.length + ' ses yüklendi' + (bad.length ? ' — yüklenemeyen: ' + bad.length : ''); const sx = files.some((f) => f.startsWith('s5/')); const nt = document.createElement('div'); nt.className = 'note'; nt.textContent = sx ? 'Bu YEREL sayfa: Gerçekçi sütununda Sonniss kayıtları da çalıyor (gerçek ateş, elektrik ve gök gürültüsü, buz çatlaması, ete giren bıçak, zırh, taş, asit cızırtısı). Lisansları yüzünden bu sayfa internete konmaz.' : 'Herkese açık sayfa: Gerçekçi sütunu yalnız ücretsiz CC0 kayıtlarla. Sonniss kayıtlı tam hâli yalnız yerel sayfada ve oyunun içinde.'; app.before(nt); app.before(st); go.remove(); render();
  } catch (e) { go.disabled = false; go.textContent = 'Yüklenemedi, tekrar dene (' + (e && e.message || e) + ')'; }
};
